function storeCard(s){return `<article class="store-card" data-store-index="${stores.indexOf(s)}" tabindex="0"><div class="store-image"><img src="${s.image}" alt="${s.name}" loading="lazy"><span class="store-badge">${s.badge}</span><button class="heart" aria-label="Guardar ${s.name}">♡</button></div><div class="store-info"><div class="store-title-row"><h3>${s.name}</h3><span class="rating">★ ${s.rating}</span></div><div class="store-meta">${s.kind}</div><div class="store-bottom"><span>Desde ${s.price}</span><span class="discount">${s.offer}</span></div></div></article>`}
document.getElementById('storeGrid').innerHTML=stores.slice(0,3).map(storeCard).join('');
document.getElementById('allStores').innerHTML=stores.map(storeCard).join('');
document.getElementById('couponList').innerHTML=coupons.map(c=>`<article class="coupon-item"><div class="coupon-emoji">${c.icon}</div><div class="coupon-copy"><b>${c.name}</b><small>${c.store} · ${c.expires}</small></div><div class="coupon-value">${c.value}<small>EN TU COMPRA</small></div><button class="coupon-code" data-copy="${c.code}">${c.code} &nbsp; ⧉</button></article>`).join('');
function transactionMarkup(t){return `<div class="transaction-row"><span class="transaction-icon">${t.icon}</span><span class="transaction-copy"><b>${t.name}</b><small>${t.detail}</small></span><span class="transaction-amount">${t.amount}<small>${t.currency}</small></span></div>`}
document.getElementById('transactions').innerHTML=transactions.slice(0,3).map(transactionMarkup).join('');
document.getElementById('allTransactions').innerHTML=transactions.map(transactionMarkup).join('');
const views=['inicio','tiendas','cuponera','billetera','actividad'];
function showView(name){if(!views.includes(name))name='inicio';document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active-view',v.id===`view-${name}`));document.querySelectorAll('.nav-item').forEach(a=>a.classList.toggle('active',a.dataset.view===name));document.getElementById('crumb').textContent={inicio:'Mapa',tiendas:'Tiendas',cuponera:'Cuponera',billetera:'Mi wallet',actividad:'Actividad'}[name];history.replaceState(null,'',`#${name}`);window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav-item').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showView(a.dataset.view)}));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.go)));
const initial=location.hash.slice(1);showView(views.includes(initial)?initial:'inicio');
const rate=4000,localAmount=document.getElementById('localAmount');
function updateConversion(){const amount=Number(localAmount.value)||0;document.getElementById('convertedAmount').textContent=`$ ${(amount/rate).toFixed(2)} USD`}
localAmount.addEventListener('input',updateConversion);
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>el.classList.remove('show'),2500)}
document.querySelectorAll('[data-copy]').forEach(btn=>btn.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(btn.dataset.copy);toast(`Cupón ${btn.dataset.copy} copiado`)}catch{toast(`Tu código: ${btn.dataset.copy}`)}}));
document.querySelectorAll('.heart').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();btn.textContent=btn.textContent==='♡'?'♥':'♡';btn.style.color=btn.textContent==='♥'?'#e87967':'';toast(btn.textContent==='♥'?'Guardado en tus favoritos':'Quitado de favoritos')}));
document.querySelectorAll('.filter-chip').forEach(btn=>btn.addEventListener('click',()=>{if(btn.closest('.filter-row')){btn.closest('.filter-row').querySelectorAll('.filter-chip').forEach(x=>x.classList.remove('chosen'));btn.classList.add('chosen')}}));
const modal=document.getElementById('modal');function openModal(title,text){document.getElementById('modalTitle').textContent=title;document.getElementById('modalText').textContent=text;modal.classList.add('open')};function closeModal(){modal.classList.remove('open')}
document.getElementById('closeModal').addEventListener('click',closeModal);document.getElementById('modalDone').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
document.getElementById('payNow').addEventListener('click',()=>{const amount=Number(localAmount.value)||0;openModal('¿Confirmar tu compra?',`Vas a pagar COP ${amount.toLocaleString('es-CO')} (aprox. $ ${(amount/rate).toFixed(2)} USD). La tasa final se confirma al procesar el pago.`)});
document.getElementById('addFunds').addEventListener('click',()=>openModal('Agregar saldo','Conecta una tarjeta o cuenta bancaria para recargar tu billetera Lokora. Esta opción estará disponible al activar los pagos.'));
const currencyToggle=document.getElementById('currencyToggle');if(currencyToggle)currencyToggle.addEventListener('click',()=>{const code=document.getElementById('currencyCode'),flag=document.getElementById('currencyFlag');if(code.textContent==='USD'){code.textContent='EUR';flag.textContent='🇪🇺';toast('Moneda de referencia: EUR')}else{code.textContent='USD';flag.textContent='🇺🇸';toast('Moneda de referencia: USD')}});
const localPrices=[85000,48000,168000,16000,112000,260000];
function selectMapStore(index){const store=stores[index];if(!store)return;document.querySelectorAll('.map-pin').forEach(pin=>pin.classList.toggle('active',Number(pin.dataset.store)===index));const root=document.getElementById('mapSelectedStore');root.innerHTML=`<img class="map-selected-image" src="${store.image}" alt="${store.name}"><div class="map-selected-info"><div class="map-selected-top"><h3>${store.name}</h3><span class="map-selected-rating">★ ${store.rating}</span></div><div class="map-selected-kind">${store.kind}</div><div class="map-selected-foot"><span class="map-selected-price">COP ${localPrices[index].toLocaleString('es-CO')} <small>· ≈ $${(localPrices[index]/4000).toFixed(2)} USD</small></span><span class="map-selected-offer">${store.offer}</span><button class="map-selected-open" data-store-detail="${index}">Ver tienda</button></div></div>`;root.querySelector('[data-store-detail]').addEventListener('click',()=>openStoreDetail(index))}
document.querySelectorAll('.map-pin').forEach(pin=>pin.addEventListener('click',()=>selectMapStore(Number(pin.dataset.store))));
['storeGrid','allStores'].forEach(id=>document.getElementById(id).addEventListener('click',e=>{const card=e.target.closest('[data-store-index]');if(card&&!e.target.closest('.heart'))openStoreDetail(Number(card.dataset.storeIndex))}));
['storeGrid','allStores'].forEach(id=>document.getElementById(id).addEventListener('keydown',e=>{const card=e.target.closest('[data-store-index]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openStoreDetail(Number(card.dataset.storeIndex))}}));
selectMapStore(0);
document.getElementById('mapListToggle').addEventListener('click',()=>showView('tiendas'));
document.getElementById('locateMe').addEventListener('click',()=>toast('Mostrando tiendas cerca del centro de Medellín'));
document.getElementById('mapFilter').addEventListener('click',e=>{const button=e.currentTarget;button.classList.toggle('filter-active');const filtered=button.classList.contains('filter-active');button.innerHTML=filtered?'✓ <span>Con descuento</span>':'☷ <span>Filtros</span>';document.querySelectorAll('.map-pin').forEach((pin,index)=>pin.hidden=filtered&&index===3);stores.forEach((store,index)=>{if(store.marker)store.marker.setMap(!filtered||index!==3?window.lokoraGoogleMap:null)})});
document.getElementById('mapSearch').addEventListener('input',e=>{const query=e.target.value.trim().toLocaleLowerCase('es');document.querySelectorAll('.map-pin').forEach((pin,index)=>{const store=stores[index],matches=!query||(`${store.name} ${store.kind} ${store.location}`.toLocaleLowerCase('es').includes(query));pin.hidden=!matches;if(store.marker)store.marker.setMap(matches?window.lokoraGoogleMap:null)})});
function openStoreDetail(index){const store=stores[index];if(!store)return;document.getElementById('storeDetailImage').src=store.image;document.getElementById('storeDetailImage').alt=store.name;document.getElementById('storeDetailLogo').textContent=store.emoji;document.getElementById('storeDetailType').textContent=store.kind;document.getElementById('storeDetailName').textContent=store.name;document.getElementById('storeDetailRating').textContent=`★ ${store.rating} · Recomendado por viajeros`;document.getElementById('storeDetailDescription').textContent=store.description;document.getElementById('storeDetailLocation').textContent=`⌖ ${store.location}`;document.getElementById('storeDetailPrice').textContent=`Desde ${store.price}`;document.getElementById('storeDetailOffer').textContent=store.offer;const modal=document.getElementById('storeDetailModal');modal.classList.add('open');modal.setAttribute('aria-hidden','false')}
function closeStoreDetail(){const modal=document.getElementById('storeDetailModal');modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}
document.getElementById('closeStoreDetail').addEventListener('click',closeStoreDetail);document.getElementById('storeDetailModal').addEventListener('click',e=>{if(e.target.id==='storeDetailModal')closeStoreDetail()});document.getElementById('storeDetailBrowse').addEventListener('click',()=>{closeStoreDetail();showView('tiendas')});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeStoreDetail()});
function initGoogleMap(){const layer=document.getElementById('googleMap');if(!window.google?.maps||!layer)return;layer.style.display='block';document.querySelector('.map-drawing').style.display='none';document.querySelectorAll('.map-pin').forEach(pin=>pin.style.display='none');document.getElementById('mapStatus').textContent='Google Maps · Medellín';const map=new google.maps.Map(layer,{center:{lat:6.2442,lng:-75.5812},zoom:13,clickableIcons:false,mapTypeControl:false,streetViewControl:false,fullscreenControl:false,gestureHandling:'greedy',styles:[{featureType:'poi',elementType:'labels',stylers:[{visibility:'off'}]},{featureType:'landscape',elementType:'geometry',stylers:[{color:'#f8f4e7'}]},{featureType:'water',elementType:'geometry',stylers:[{color:'#c8dfdf'}]},{featureType:'road',elementType:'geometry',stylers:[{color:'#fffdf8'}]},{featureType:'road.highway',elementType:'geometry',stylers:[{color:'#f0d99b'}]}]});window.lokoraGoogleMap=map;stores.forEach((store,index)=>{const price=Math.round(localPrices[index]/4000),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="78" height="42" viewBox="0 0 78 42"><rect x="1" y="1" width="76" height="35" rx="12" fill="${index===0?'#1e3a52':'#fffdf8'}" stroke="#a12d4a" stroke-width="2"/><text x="39" y="24" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="${index===0?'#ffffff':'#1e3a52'}">$${price}</text><path d="M33 35h12l-6 7z" fill="${index===0?'#1e3a52':'#fffdf8'}" stroke="#a12d4a" stroke-width="1"/></svg>`;const marker=new google.maps.Marker({map,position:store.position,title:`${store.name} · ★ ${store.rating}`,icon:{url:'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg),scaledSize:new google.maps.Size(78,42),anchor:new google.maps.Point(39,42)}});marker.addListener('click',()=>selectMapStore(index));store.marker=marker});document.getElementById('locateMe').addEventListener('click',()=>map.panTo({lat:6.2442,lng:-75.5812}))}
window.gm_authFailure=()=>{document.getElementById('mapStatus').textContent='Revisa la clave de Google Maps'};
const mapsKey=document.querySelector('meta[name="google-maps-api-key"]')?.content;if(mapsKey&&mapsKey!=='__GOOGLE_MAPS_API_KEY__'){const mapsScript=document.createElement('script');mapsScript.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(mapsKey)}&callback=initGoogleMap&loading=async&v=weekly`;mapsScript.async=true;mapsScript.defer=true;mapsScript.onerror=()=>document.getElementById('mapStatus').textContent='Mapa de demostración · configura la API de Google Maps';document.head.appendChild(mapsScript)}
